/* saleson.shop.order.refund.OrderRefundMapper.getOrderRefundCountByParam */ SELECT COUNT(1) FROM ( SELECT V1.REFUND_CODE , V1.REFUND_DATE , V1.ORDER_CODE , V1.ORDER_SEQUENCE , V1.REFUND_STATUS_CODE , V1.REQUEST_MANAGER_USER_NAME , V1.PROCESS_MANAGER_USER_NAME , V1.RETURN_BANK_NAME , V1.RETURN_VIRTUAL_NO , V1.RETURN_BANK_IN_NAME , V1.CREATED_DATE , V1.UPDATED_DATE , V1.BUYER_NAME , V1.LOGIN_ID , V1.USER_ID , V1.ORDER_DATE , V1.LOCGOV_CODE FROM ( SELECT R.REFUND_CODE , R.REFUND_DATE , R.ORDER_CODE , R.ORDER_SEQUENCE , R.REFUND_STATUS_CODE , R.REQUEST_MANAGER_USER_NAME , R.PROCESS_MANAGER_USER_NAME , R.RETURN_BANK_NAME , R.RETURN_VIRTUAL_NO , R.RETURN_BANK_IN_NAME , R.CREATED_DATE , R.UPDATED_DATE , O.BUYER_NAME , O.LOGIN_ID , O.USER_ID , O.CREATED_DATE AS ORDER_DATE , S.LOCGOV_CODE FROM OP_ORDER_REFUND R , OP_ORDER O , OP_ORDER_CANCEL_APPLY C , OP_ORDER_ITEM I , OP_SELLER S WHERE R.ORDER_CODE = O.ORDER_CODE AND R.ORDER_SEQUENCE = O.ORDER_SEQUENCE AND R.REFUND_CODE = C.REFUND_CODE AND C.ORDER_CODE = I.ORDER_CODE AND C.ORDER_SEQUENCE = I.ORDER_SEQUENCE AND C.ITEM_SEQUENCE = I.ITEM_SEQUENCE AND I.SELLER_ID = S.SELLER_ID AND O.DATA_STATUS_CODE = '1'
AND R.REFUND_STATUS_CODE = #{refundStatusCode}
AND DATE_FORMAT(R.CREATED_DATE, '%Y%m%d') BETWEEN #{searchStartDate} AND #{searchEndDate}
AND O.BUYER_NAME LIKE CONCAT('%', #{query}, '%')
AND O.LOGIN_ID LIKE CONCAT('%', #{query},'%')
AND R.REFUND_CODE LIKE CONCAT('%', #{query}, '%')
AND R.ORDER_CODE LIKE CONCAT('%', #{query}, '%')
AND I.ITEM_NAME LIKE CONCAT('%', #{query}, '%')
AND I.ITEM_ID IN ( SELECT ITEM_ID FROM OP_ITEM WHERE ITEM_SELLER_CODE LIKE CONCAT('%', #{query}, '%') )
AND S.LOCGOV_CODE = #{shLocgovCode}
AND I.SELLER_ID = #{sellerId}
AND (
R.REFUND_DATE >= CONCAT(DATE_FORMAT(ADD_MONTHS(CURRENT_DATETIME, -1), '%Y%m'), '01') OR R.REFUND_STATUS_CODE <> '2' )
UNION ALL SELECT R.REFUND_CODE , R.REFUND_DATE , R.ORDER_CODE , R.ORDER_SEQUENCE , R.REFUND_STATUS_CODE , R.REQUEST_MANAGER_USER_NAME , R.PROCESS_MANAGER_USER_NAME , R.RETURN_BANK_NAME , R.RETURN_VIRTUAL_NO , R.RETURN_BANK_IN_NAME , R.CREATED_DATE , R.UPDATED_DATE , O.BUYER_NAME , O.LOGIN_ID , O.USER_ID , O.CREATED_DATE AS ORDER_DATE , S.LOCGOV_CODE FROM OP_ORDER_REFUND R , OP_ORDER O , OP_ORDER_RETURN_APPLY C , OP_ORDER_ITEM I , OP_SELLER S WHERE R.ORDER_CODE = O.ORDER_CODE AND R.ORDER_SEQUENCE = O.ORDER_SEQUENCE AND R.REFUND_CODE = C.REFUND_CODE AND C.ORDER_CODE = I.ORDER_CODE AND C.ORDER_SEQUENCE = I.ORDER_SEQUENCE AND C.ITEM_SEQUENCE = I.ITEM_SEQUENCE AND I.SELLER_ID = S.SELLER_ID AND O.DATA_STATUS_CODE = '1'
AND R.REFUND_STATUS_CODE = #{refundStatusCode}
AND DATE_FORMAT(R.CREATED_DATE, '%Y%m%d') BETWEEN #{searchStartDate} AND #{searchEndDate}
AND O.BUYER_NAME LIKE CONCAT('%', #{query}, '%')
AND O.LOGIN_ID LIKE CONCAT('%', #{query},'%')
AND R.REFUND_CODE LIKE CONCAT('%', #{query}, '%')
AND R.ORDER_CODE LIKE CONCAT('%', #{query}, '%')
AND I.ITEM_NAME LIKE CONCAT('%', #{query}, '%')
AND I.ITEM_ID IN ( SELECT ITEM_ID FROM OP_ITEM WHERE ITEM_SELLER_CODE LIKE CONCAT('%', #{query}, '%') )
AND S.LOCGOV_CODE = #{shLocgovCode}
AND I.SELLER_ID = #{sellerId}
AND (
R.REFUND_DATE >= CONCAT(DATE_FORMAT(ADD_MONTHS(CURRENT_DATETIME, -1), '%Y%m'), '01') OR R.REFUND_STATUS_CODE <> '2' )
) V1 GROUP BY V1.REFUND_CODE , V1.REFUND_DATE , V1.ORDER_CODE , V1.ORDER_SEQUENCE , V1.REFUND_STATUS_CODE , V1.REQUEST_MANAGER_USER_NAME , V1.PROCESS_MANAGER_USER_NAME , V1.RETURN_BANK_NAME , V1.RETURN_VIRTUAL_NO , V1.RETURN_BANK_IN_NAME , V1.CREATED_DATE , V1.UPDATED_DATE , V1.BUYER_NAME , V1.LOGIN_ID , V1.USER_ID , V1.ORDER_DATE , V1.LOCGOV_CODE ) V , G_LOCGOV L , OP_USER U WHERE V.LOCGOV_CODE = L.LOCGOV_CODE AND V.USER_ID = U.USER_ID ORDER BY V.CREATED_DATE DESC

