AND (
R.REFUND_DATE >= CONCAT(DATE_FORMAT(ADD_MONTHS(CURRENT_DATETIME, -1), '%Y%m'), '01') OR R.REFUND_STATUS_CODE <> '2' )
UNION ALL SELECT R.REFUND_CODE , R.REFUND_DATE , R.ORDER_CODE , R.ORDER_SEQUENCE , R.REFUND_STATUS_CODE , R.REQUEST_MANAGER_USER_NAME , R.PROCESS_MANAGER_USER_NAME , R.RETURN_BANK_NAME , R.RETURN_VIRTUAL_NO , R.RETURN_BANK_IN_NAME , R.CREATED_DATE , R.UPDATED_DATE , O.BUYER_NAME , O.LOGIN_ID , O.USER_ID , O.CREATED_DATE AS ORDER_DATE , S.LOCGOV_CODE , I.ITEM_NAME , I.OPTIONS , I.ITEM_USER_CODE FROM OP_ORDER_REFUND R , OP_ORDER O , OP_ORDER_RETURN_APPLY C , OP_ORDER_ITEM I , OP_SELLER S WHERE R.ORDER_CODE = O.ORDER_CODE AND R.ORDER_SEQUENCE = O.ORDER_SEQUENCE AND R.REFUND_CODE = C.REFUND_CODE AND C.ORDER_CODE = I.ORDER_CODE AND C.ORDER_SEQUENCE = I.ORDER_SEQUENCE AND C.ITEM_SEQUENCE = I.ITEM_SEQUENCE AND I.SELLER_ID = S.SELLER_ID AND O.DATA_STATUS_CODE = '1'
AND R.REFUND_STATUS_CODE = #{refundStatusCode}
AND DATE_FORMAT(R.CREATED_DATE, '%Y%m%d') BETWEEN #{searchStartDate} AND #{searchEndDate}
AND O.BUYER_NAME LIKE CONCAT('%', #{query}, '%')
AND O.LOGIN_ID LIKE CONCAT('%', #{query},'%')
AND R.REFUND_CODE LIKE CONCAT('%', #{query}, '%')
AND R.ORDER_CODE LIKE CONCAT('%', #{query}, '%')
