AND S.LOCGOV_CODE = #{shLocgovCode}
AND I.SELLER_ID = #{sellerId}
AND (
R.REFUND_DATE >= CONCAT(DATE_FORMAT(ADD_MONTHS(CURRENT_DATETIME, -1), '%Y%m'), '01') OR R.REFUND_STATUS_CODE <> '2' )
) V1 GROUP BY V1.REFUND_CODE , V1.REFUND_DATE , V1.ORDER_CODE , V1.ORDER_SEQUENCE , V1.REFUND_STATUS_CODE , V1.REQUEST_MANAGER_USER_NAME , V1.PROCESS_MANAGER_USER_NAME , V1.RETURN_BANK_NAME , V1.RETURN_VIRTUAL_NO , V1.RETURN_BANK_IN_NAME , V1.CREATED_DATE , V1.UPDATED_DATE , V1.BUYER_NAME , V1.LOGIN_ID , V1.USER_ID , V1.ORDER_DATE , V1.LOCGOV_CODE ) V , G_LOCGOV L , OP_USER U WHERE V.LOCGOV_CODE = L.LOCGOV_CODE AND V.USER_ID = U.USER_ID ORDER BY V.CREATED_DATE DESC

/* saleson.shop.order.refund.OrderRefundMapper.getActiveRefundCodeByParam */ SELECT REFUND_CODE FROM OP_ORDER_REFUND A
A.ORDER_CODE = #{orderCode} AND A.ORDER_SEQUENCE = #{orderSequence} AND A.REFUND_STATUS_CODE = '1' AND EXISTS ( SELECT 1 FROM OP_ORDER_RETURN_APPLY R , OP_ORDER_ITEM I , OP_SELLER S WHERE R.ORDER_CODE = I.ORDER_CODE AND R.ORDER_SEQUENCE = I.ORDER_SEQUENCE AND R.ITEM_SEQUENCE = I.ITEM_SEQUENCE AND I.SELLER_ID = S.SELLER_ID AND A.ORDER_CODE = I.ORDER_CODE AND A.ORDER_SEQUENCE = I.ORDER_SEQUENCE AND R.REFUND_CODE = A.REFUND_CODE AND R.REFUND_CODE IS NOT NULL
AND S.LOCGOV_CODE = #{shLocgovCode}
AND I.SELLER_ID = #{sellerId}
)

mapper.update:
/* saleson.shop.order.refund.OrderRefundMapper.updateRefundFinishedForItem */ UPDATE OP_ORDER_ITEM OI INNER JOIN ( SELECT 'CANCEL' AS TYPE, ITEM_SEQUENCE FROM OP_ORDER_CANCEL_APPLY WHERE REFUND_CODE = #{refundCode}
UNION
SELECT 'RETURN' AS TYPE, ITEM_SEQUENCE FROM OP_ORDER_RETURN_APPLY WHERE REFUND_CODE = #{refundCode}
) TARGET ON OI.ITEM_SEQUENCE = TARGET.ITEM_SEQUENCE SET OI.CANCEL_FLAG = 'Y', OI.REFUND_STATUS = '2', OI.SALES_CANCEL_DATE = , OI.CANCEL_REQUEST_FINISH_DATE = ( CASE WHEN TARGET.TYPE = 'CANCEL' THEN
ELSE '00000000000000' END ), OI.RETURN_REQUEST_FINISH_DATE = ( CASE WHEN TARGET.TYPE = 'RETURN' THEN
ELSE '00000000000000' END ), OI.ORDER_STATUS = ( CASE WHEN TARGET.TYPE = 'CANCEL' THEN '75' ELSE '65' END )
ORDER_CODE = #{orderCode} AND ORDER_SEQUENCE = #{orderSequence}

mapper.delete:
