DELETE FROM OP_ORDER_REFUND

	REFUND_CODE = #{refundCode}
	AND ORDER_CODE = #{orderCode}
	AND ORDER_SEQUENCE = #{orderSequence}
	AND REFUND_STATUS_CODE = '1'

